using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Diagnostics;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using Mcrf.Wpf;
using SplifyWin;
class DeploymentIntegration20261013 {
 static int checks;static string root;
 static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static void Reject(Action action,string label){bool rejected=false;try{action();}catch(FormatException){rejected=true;}catch(IOException){rejected=true;}Check(rejected,label);}
 static DeployTarget Target(){return new DeployTarget{Host="192.0.2.1",User="root",Password="fixture-ssh-password",PanelUser="fixture-user",PanelPassword="fixture-panel-password"};}
 static DeployResult Result(string[] links){return new DeployResult{ready=true,panel_url="https://192.0.2.1:8443/fixture/",username="fixture-user",password="fixture-panel-password",certificate_sha256=new string('a',64),connections=links,provision_requested=true,provision_complete=true};}
 static int Main(string[] args){try{root=Path.GetFullPath(args[0]);if(Directory.Exists(root))throw new Exception("Fresh fixture required");Directory.CreateDirectory(root);ManagedDependencies.Ensure();Run(args[1],args[2],args[3]);Console.WriteLine("OK "+checks+" deployment integration checks; no remote server changed.");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
 [MethodImpl(MethodImplOptions.NoInlining)]static void Run(string python,string tests,string installer){
  var target=Target();target.Validate();
  var openfluxRecipe=DeployRecipe.All.Single(r=>r.Id=="openflux");string source=File.ReadAllText(installer).Replace("\r\n","\n");Check(AppUpdates.Hash(Encoding.UTF8.GetBytes(source))==openfluxRecipe.Sha256,"OpenFlux fixture is the pinned upstream installer");string pinned=Deployment.PinInstaller(openfluxRecipe,source);File.WriteAllText(Path.Combine(root,"openflux-installer.sh"),pinned,new UTF8Encoding(false));Check(pinned.Contains("toolchain=\"$STATE_DIR/toolchains/go$version\"")&&!pinned.Contains("rm -rf /usr/local/go")&&!pinned.Contains("ln -sf /usr/local/go"),"OpenFlux Go isolated; system toolchain never replaced");Check(pinned.Contains(openfluxRecipe.Commit)&&pinned.Contains(openfluxRecipe.CoreCommit),"both OpenFlux source revisions pinned");Check(pinned.Contains("sha256sum -c")&&pinned.Contains("export GOMODCACHE="),"isolated toolchain checksum and private build cache enforced");Reject(()=>Deployment.PinInstaller(openfluxRecipe,source.Replace("install_go(){","unexpected_go(){")),"unrecognized Go installer rejected before SSH");
  foreach(var recipe in DeployRecipe.All){target.Provision=new DeployProvisionOptions{create=true,vk_call="https://vk.ru/call/join/"+new string('A',43)};target.Provision.Validate(recipe.Id,target);var script=Deployment.BuildScript(recipe,target,"/tmp/mcrf-deploy-"+new string('a',32));Check(script.Contains("class PanelAPI:")&&script.Contains("def configure_initial("),recipe.Id+" provision source embedded in single EXE");Check(script.Contains("MCRF_PROVISION_OPTIONS=")&&script.Contains("MCRF_PROVISION_KIND='"+recipe.Id+"'"),recipe.Id+" options reach server script");Check(!script.Contains(target.Password),recipe.Id+" SSH password never copied into server script");File.WriteAllText(Path.Combine(root,recipe.Id+"-fixture.sh"),script,new UTF8Encoding(false));}
  target.Provision=new DeployProvisionOptions{create=true};Reject(()=>{target.Provision.tcp=false;target.Provision.grpc=false;target.Provision.Validate("3xui",target);},"empty TCP/gRPC selection rejected");
  foreach(int invalid in new[]{22,8443,1023,65536}){target.Provision=new DeployProvisionOptions{create=true,tcp_port=invalid};Reject(()=>target.Provision.Validate("3xui",target),"reserved/invalid connection port "+invalid+" rejected");}
  target.Provision=new DeployProvisionOptions{create=true,tcp_port=15931};Reject(()=>target.Provision.Validate("3xui",target),"TCP/gRPC collision rejected");
  foreach(string invalid in new[]{"https://example.test","example.test/path","example.test\nexport X=1"}){target.Provision=new DeployProvisionOptions{create=true,sni=invalid};Reject(()=>target.Provision.Validate("3xui",target),"invalid SNI rejected");}
  foreach(string kind in new[]{"direct","yandex","vyandex","boards","telemost","mailru","cupsonline"}){target.Provision=new DeployProvisionOptions{create=true,transport=kind,carrier_url="https://fixture.example/document"};target.Provision.Validate("openflux",target);Check(true,"OpenFlux carrier "+kind+" selectable");}
  target.Provision=new DeployProvisionOptions{create=true,transport="yandex",carrier_url="http://fixture.example"};Reject(()=>target.Provision.Validate("openflux",target),"non-HTTPS carrier rejected");
  foreach(string kind in new[]{"qwdtt","wdtt","csqtt"}){target.Provision=new DeployProvisionOptions{create=true,relay_kind=kind,vk_call=new string('A',43)};target.Provision.Validate("swg",target);Check(target.Provision.vk_call.StartsWith("https://vk.ru/call/join/"),kind+" hash normalized to call URL");}
  target.Provision=new DeployProvisionOptions{create=true,relay_kind="qwdtt",vk_call="not a call"};Reject(()=>target.Provision.Validate("swg",target),"invalid VK call rejected");
  var output=new StringBuilder();using(var process=Process.Start(new ProcessStartInfo(python,"-X utf8 \""+Path.GetFullPath(tests)+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8})){var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(15000)){process.Kill();throw new TimeoutException("Python fixture");}output.Append(stdout.GetAwaiter().GetResult());Check(process.ExitCode==0,"Python provision fixtures pass");}
  var links=output.ToString().Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Where(l=>l.StartsWith("MCRF_TEST_LINK|")).Select(l=>Encoding.UTF8.GetString(Convert.FromBase64String(l.Substring(15)))).Distinct().ToArray();Check(links.Length==6,"six generated share links received from real serializers");var core=new NetworkCore(new StateStore(Path.Combine(root,"profile")));
  foreach(string link in links){var node=Links.Read(link).Single();core.ValidateImport(node);Check(node.Name.Contains("MCRF")||node.Protocol=="openflux",node.Protocol+" name survives query escaping");Check(!node.Name.Contains("+"),node.Protocol+" spaces are not literal plus signs");Deployment.ValidateResult(Result(new[]{link}),target);Check(true,node.Protocol+" result imports through actual Windows parser");if(node.Protocol=="vless"){var state=new ClientState{Mode="proxy",IndependentWarpOutputs=true,VpnEnabled=true,AutoSelect=false,SelectedServerId=node.Id,Servers=new List<ServerNode>{node}};core.Check(core.WriteConfig(state));Check(true,node.Protocol+" TCP/gRPC generated profile accepted by bundled sing-box");}}
  Reject(()=>Deployment.ValidateResult(Result(new string[0]),target),"success without connection rejected");var bad=Result(links);bad.certificate_sha256="wrong";Reject(()=>Deployment.ValidateResult(bad,target),"missing TLS pin rejected");bad=Result(links);bad.panel_url="http://192.0.2.1:8443";Reject(()=>Deployment.ValidateResult(bad,target),"plaintext panel result rejected");Reject(()=>Deployment.ValidateResult(Result(new[]{"https://fixture.example"}),target),"unexpected profile protocol rejected");var partial=Result(new[]{links[4]});partial.provision_complete=false;partial.provision_error="second profile incomplete";Deployment.ValidateResult(partial,target);Check(true,"confirmed partial result remains importable");core.Stop();
 }
}
